class KeyValueStore:
    def __init__(self, filename):
        self.filename = filename
        try:
            with open(self.filename, 'rb') as f:
                self.store = pickle.load(f)
        except FileNotFoundError:
            self.store = {}

    def set(self, key, value, callback=None):
        self.store[key] = value
        if callback:
            threading.Thread(target=self.calculate_sum, args=(key, callback)).start()
        self.save()

    def calculate_sum(self, key, callback):
        time.sleep(3)
        total = sum(self.store.values())
