    global ID
    global TODOS
    if 'id' not in todo:
        todo['id'] = ID
        ID += 1
    parsed_due_date = dateutil.parser.parse(todo['due_date']).date()
    TODOS[todo['id']] = {'due_date': parsed_due_date, **todo}

@app.route('/todos', methods=['POST'])
